/* =========================================================
   DICOM PARSER — EXTRACTED CORE FUNCTIONS
   Based on dicom-parser 1.8.12
   ========================================================= */

const DICOM_STRING_VR = {
    AE: true,
    AS: true,
    AT: false,
    CS: true,
    DA: true,
    DS: true,
    DT: true,
    FL: false,
    FD: false,
    IS: true,
    LO: true,
    LT: true,
    OB: false,
    OD: false,
    OF: false,
    OW: false,
    PN: true,
    SH: true,
    SL: false,
    SQ: false,
    SS: false,
    ST: true,
    TM: true,
    UI: true,
    UL: false,
    UN: undefined,
    UR: true,
    US: false,
    UT: true
};

function isStringVr(vr) {
    return DICOM_STRING_VR[vr];
}

function isPrivateTag(tag) {
    const value = parseInt(tag[4], 16);

    if (isNaN(value)) {
        throw new Error(
            "dicomParser.isPrivateTag: cannot parse last character of group"
        );
    }

    return value % 2 === 1;
}


/* =========================================================
   READ FIXED STRING
   ========================================================= */

function readFixedString(byteArray, offset, length) {

    if (length < 0) {
        throw new Error(
            "dicomParser.readFixedString - length cannot be less than 0"
        );
    }

    if (offset + length > byteArray.length) {
        throw new Error(
            "dicomParser.readFixedString: attempt to read past end of buffer"
        );
    }

    let result = "";

    for (let i = 0; i < length; i++) {

        const value = byteArray[offset + i];

        if (value === 0) {
            break;
        }

        result += String.fromCharCode(value);
    }

    return result;
}


/* =========================================================
   LITTLE ENDIAN PARSER
   ========================================================= */

const littleEndianByteArrayParser = {

    readUint16(byteArray, position) {

        if (position < 0) {
            throw new Error(
                "littleEndianByteArrayParser.readUint16: position cannot be less than 0"
            );
        }

        if (position + 2 > byteArray.length) {
            throw new Error(
                "littleEndianByteArrayParser.readUint16: attempt to read past end of buffer"
            );
        }

        return byteArray[position] +
            256 * byteArray[position + 1];
    },


    readInt16(byteArray, position) {

        let value =
            byteArray[position] +
            (byteArray[position + 1] << 8);

        return value & 0x8000
            ? value - 65536
            : value;
    },


    readUint32(byteArray, position) {

        if (position < 0) {
            throw new Error(
                "littleEndianByteArrayParser.readUint32: position cannot be less than 0"
            );
        }

        if (position + 4 > byteArray.length) {
            throw new Error(
                "littleEndianByteArrayParser.readUint32: attempt to read past end of buffer"
            );
        }

        return (
            byteArray[position] +
            256 * byteArray[position + 1] +
            65536 * byteArray[position + 2] +
            16777216 * byteArray[position + 3]
        );
    },


    readInt32(byteArray, position) {

        return (
            byteArray[position] |
            (byteArray[position + 1] << 8) |
            (byteArray[position + 2] << 16) |
            (byteArray[position + 3] << 24)
        );
    },


    readFloat(byteArray, position) {

        const buffer = new ArrayBuffer(4);
        const view = new Uint8Array(buffer);

        view[0] = byteArray[position];
        view[1] = byteArray[position + 1];
        view[2] = byteArray[position + 2];
        view[3] = byteArray[position + 3];

        return new Float32Array(buffer)[0];
    },


    readDouble(byteArray, position) {

        const buffer = new ArrayBuffer(8);
        const view = new Uint8Array(buffer);

        for (let i = 0; i < 8; i++) {
            view[i] = byteArray[position + i];
        }

        return new Float64Array(buffer)[0];
    }
};


/* =========================================================
   BIG ENDIAN PARSER
   ========================================================= */

const bigEndianByteArrayParser = {

    readUint16(byteArray, position) {

        return (
            (byteArray[position] << 8) |
            byteArray[position + 1]
        );
    },


    readInt16(byteArray, position) {

        let value =
            (byteArray[position] << 8) |
            byteArray[position + 1];

        return value & 0x8000
            ? value - 65536
            : value;
    },


    readUint32(byteArray, position) {

        return (
            256 * (
                256 * (
                    256 * byteArray[position] +
                    byteArray[position + 1]
                ) +
                byteArray[position + 2]
            ) +
            byteArray[position + 3]
        );
    },


    readInt32(byteArray, position) {

        return (
            (byteArray[position] << 24) |
            (byteArray[position + 1] << 16) |
            (byteArray[position + 2] << 8) |
            byteArray[position + 3]
        );
    },


    readFloat(byteArray, position) {

        const buffer = new ArrayBuffer(4);
        const view = new Uint8Array(buffer);

        view[3] = byteArray[position];
        view[2] = byteArray[position + 1];
        view[1] = byteArray[position + 2];
        view[0] = byteArray[position + 3];

        return new Float32Array(buffer)[0];
    },


    readDouble(byteArray, position) {

        const buffer = new ArrayBuffer(8);
        const view = new Uint8Array(buffer);

        for (let i = 0; i < 8; i++) {
            view[7 - i] = byteArray[position + i];
        }

        return new Float64Array(buffer)[0];
    }
};


/* =========================================================
   BYTE STREAM
   ========================================================= */

class ByteStream {

    constructor(byteArrayParser, byteArray, position = 0) {

        if (!byteArrayParser) {
            throw new Error(
                "ByteStream: missing byteArrayParser"
            );
        }

        if (!byteArray) {
            throw new Error(
                "ByteStream: missing byteArray"
            );
        }

        this.byteArrayParser = byteArrayParser;
        this.byteArray = byteArray;
        this.position = position;
        this.warnings = [];
    }


    seek(offset) {

        const newPosition = this.position + offset;

        if (newPosition < 0) {
            throw new Error(
                "ByteStream.seek: position cannot be less than 0"
            );
        }

        this.position = newPosition;
    }


    getSize() {
        return this.byteArray.length;
    }


    readUint16() {

        const value =
            this.byteArrayParser.readUint16(
                this.byteArray,
                this.position
            );

        this.position += 2;

        return value;
    }


    readUint32() {

        const value =
            this.byteArrayParser.readUint32(
                this.byteArray,
                this.position
            );

        this.position += 4;

        return value;
    }


    readFixedString(length) {

        const value =
            readFixedString(
                this.byteArray,
                this.position,
                length
            );

        this.position += length;

        return value;
    }
}


/* =========================================================
   READ DICOM TAG
   ========================================================= */

function readTag(byteStream) {

    const group = byteStream.readUint16();
    const element = byteStream.readUint16();

    return (
        "x" +
        ("00000000" +
            (
                group * 65536 +
                element
            ).toString(16)
        ).slice(-8)
    );
}


/* =========================================================
   DICOM DATASET
   ========================================================= */

class DataSet {

    constructor(byteArrayParser, byteArray, elements) {

        this.byteArrayParser = byteArrayParser;
        this.byteArray = byteArray;
        this.elements = elements;
    }


    uint16(tag, index = 0) {

        const element = this.elements[tag];

        if (!element || element.length === 0) {
            return undefined;
        }

        return this.byteArrayParser.readUint16(
            this.byteArray,
            element.dataOffset + index * 2
        );
    }


    int16(tag, index = 0) {

        const element = this.elements[tag];

        if (!element || element.length === 0) {
            return undefined;
        }

        return this.byteArrayParser.readInt16(
            this.byteArray,
            element.dataOffset + index * 2
        );
    }


    uint32(tag, index = 0) {

        const element = this.elements[tag];

        if (!element || element.length === 0) {
            return undefined;
        }

        return this.byteArrayParser.readUint32(
            this.byteArray,
            element.dataOffset + index * 4
        );
    }


    int32(tag, index = 0) {

        const element = this.elements[tag];

        if (!element || element.length === 0) {
            return undefined;
        }

        return this.byteArrayParser.readInt32(
            this.byteArray,
            element.dataOffset + index * 4
        );
    }


    float(tag, index = 0) {

        const element = this.elements[tag];

        if (!element || element.length === 0) {
            return undefined;
        }

        return this.byteArrayParser.readFloat(
            this.byteArray,
            element.dataOffset + index * 4
        );
    }


    double(tag, index = 0) {

        const element = this.elements[tag];

        if (!element || element.length === 0) {
            return undefined;
        }

        return this.byteArrayParser.readDouble(
            this.byteArray,
            element.dataOffset + index * 8
        );
    }


    string(tag, index) {

        const element = this.elements[tag];

        if (!element) {
            return undefined;
        }

        if (element.Value !== undefined) {
            return element.Value;
        }

        if (element.length === 0) {
            return undefined;
        }

        const value = readFixedString(
            this.byteArray,
            element.dataOffset,
            element.length
        );

        const values = value.split("\\");

        if (index !== undefined) {
            return values[index]?.trim();
        }

        return value.trim();
    }


    text(tag, index) {

        const value = this.string(tag, index);

        return value?.replace(/\s+$/, "");
    }


    intString(tag, index = 0) {

        const value = this.string(tag, index);

        if (value === undefined) {
            return undefined;
        }

        return parseInt(value, 10);
    }


    floatString(tag, index = 0) {

        const value = this.string(tag, index);

        if (value === undefined) {
            return undefined;
        }

        return parseFloat(value);
    }


    numStringValues(tag) {

        const element = this.elements[tag];

        if (!element || element.length === 0) {
            return undefined;
        }

        const value = readFixedString(
            this.byteArray,
            element.dataOffset,
            element.length
        );

        const matches = value.match(/\\/g);

        return matches === null
            ? 1
            : matches.length + 1;
    }
}


/* =========================================================
   READ EXPLICIT DICOM ELEMENT
   ========================================================= */

function readDicomElementExplicit(
    byteStream,
    warnings = [],
    untilTag
) {

    const tag = readTag(byteStream);

    const vr = byteStream.readFixedString(2);

    const element = {
        tag,
        vr
    };

    if (
        vr === "OB" ||
        vr === "OD" ||
        vr === "OF" ||
        vr === "OL" ||
        vr === "OW" ||
        vr === "SQ" ||
        vr === "UC" ||
        vr === "UR" ||
        vr === "UT" ||
        vr === "UN"
    ) {

        byteStream.seek(2);

        element.length =
            byteStream.readUint32();

    } else {

        element.length =
            byteStream.readUint16();
    }

    element.dataOffset =
        byteStream.position;

    if (element.length === 0xffffffff) {
        element.hadUndefinedLength = true;
    }

    if (element.tag === "x7fe00010") {

        if (element.hadUndefinedLength) {
            readEncapsulatedPixelData(
                byteStream,
                element,
                warnings
            );
        }

    } else if (vr === "SQ") {

        readSequenceItemsExplicit(
            byteStream,
            element,
            warnings
        );

    } else {

        byteStream.seek(element.length);
    }

    return element;
}


/* =========================================================
   READ PART 10 HEADER
   ========================================================= */

function readPart10Header(byteArray) {

    const byteStream =
        new ByteStream(
            littleEndianByteArrayParser,
            byteArray
        );

    const elements = {};
    const warnings = [];

    if (byteArray.length >= 132) {

        byteStream.seek(128);

        const prefix =
            byteStream.readFixedString(4);

        if (prefix !== "DICM") {

            byteStream.position = 0;

        }

    }

    while (
        byteStream.position <
        byteArray.length
    ) {

        const position =
            byteStream.position;

        const element =
            readDicomElementExplicit(
                byteStream,
                warnings
            );

        /*
         * Meta header ends at group > 0002
         */
        if (
            element.tag.substring(1, 5) !== "0002"
        ) {

            byteStream.position =
                position;

            break;
        }

        element.parser =
            littleEndianByteArrayParser;

        elements[element.tag] =
            element;
    }

    return {
        byteStream,
        elements,
        warnings
    };
}


/* =========================================================
   EXTRACT DICOM VALUE
   ========================================================= */

function getDicomValue(dataSet, tag) {

    if (!dataSet || !dataSet.elements) {
        return undefined;
    }

    const element =
        dataSet.elements[tag];

    if (!element) {
        return undefined;
    }

    if (element.Value !== undefined) {
        return element.Value;
    }

    if (element.length === 0) {
        return "";
    }

    return readFixedString(
        dataSet.byteArray,
        element.dataOffset,
        element.length
    ).trim();
}


/* =========================================================
   GET COMMON DICOM METADATA
   ========================================================= */

function extractDicomMetadata(dataSet) {

    return {

        patientName:
            getDicomValue(
                dataSet,
                "x00100010"
            ),

        patientId:
            getDicomValue(
                dataSet,
                "x00100020"
            ),

        studyDate:
            getDicomValue(
                dataSet,
                "x00080020"
            ),

        studyDescription:
            getDicomValue(
                dataSet,
                "x00081030"
            ),

        modality:
            getDicomValue(
                dataSet,
                "x00080060"
            ),

        seriesDescription:
            getDicomValue(
                dataSet,
                "x0008103e"
            ),

        rows:
            dataSet.uint16("x00280010"),

        columns:
            dataSet.uint16("x00280011"),

        bitsAllocated:
            dataSet.uint16("x00280100"),

        bitsStored:
            dataSet.uint16("x00280101"),

        highBit:
            dataSet.uint16("x00280102"),

        pixelRepresentation:
            dataSet.uint16("x00280103"),

        samplesPerPixel:
            dataSet.uint16("x00280002"),

        photometricInterpretation:
            getDicomValue(
                dataSet,
                "x00280004"
            ),

        sliceThickness:
            dataSet.floatString("x00180050"),

        sliceLocation:
            dataSet.floatString("x00201041"),

        rescaleIntercept:
            dataSet.floatString("x00281052"),

        rescaleSlope:
            dataSet.floatString("x00281053")
    };
}


/* =========================================================
   EXPORT
   ========================================================= */

window.DicomParserExtracted = {

    isStringVr,
    isPrivateTag,

    readFixedString,

    littleEndianByteArrayParser,
    bigEndianByteArrayParser,

    ByteStream,
    DataSet,

    readTag,

    readDicomElementExplicit,
    readPart10Header,

    getDicomValue,
    extractDicomMetadata
};